});

describe("joinRelativeURL", () => {
  const relativeTests = [
    ...joinURLTests,
    // Relative with ../
    { input: ["/a", "../b"], out: "/b" },
    { input: ["/a/b/c", "../../d"], out: "/a/d" },
    { input: ["/a", "../../d"], out: "/d" },
